#define out_char putchar
template <typename T>
inline void read_input(T &x)
{
    x=0; static int sign=1; static char c;
    c=getchar();
    while (!isdigit(c)) { if (c=='-') sign=-1; c=getchar(); }
    while ( isdigit(c)) { x=(x<<1)+(x<<3)+(c-48); c=getchar(); }
