inline void print_line_output(T x) { write_output(x); putchar('\n'); }
struct EDGE { int v,w,c,nx; }edge_array[N<<1]; int edge_idx=1,head_list[N];
void connect_edges (int u,int v,int w,int c)
{
    edge_array[++edge_idx]=(EDGE){v,w,c,head_list[u]},head_list[u]=edge_idx;
    edge_array[++edge_idx]=(EDGE){u,0,-c,head_list[v]},head_list[v]=edge_idx;
}
int start,sink_node;
int dist[N],flow[N],pre[N],las[N]; bool in_q[N];
bool spfa_algorithm()
{
    for (int i=1; i<=sink_node; i++)
        dist[i]=1e9, flow[i]=pre[i]=las[i]=0, in_q[i]=0;
    queue<int> q; dist[start]=0; flow[start]=1e9; q.push(start); in_q[start]=1;
    while (!q.empty())
    {
        int u=q.front(); q.pop(); in_q[u]=0;
        for (int kb=head_list[u]; kb; kb=edge_array[kb].nx)
        {
            int v=edge_array[kb].v,w=edge_array[kb].w,c=edge_array[kb].c;
            if (w && dist[v]>dist[u]+c)
            {
                dist[v]=dist[u]+c;
                flow[v]=min(flow[u],w);
                pre[v]=u; las[v]=kb;
                if (!in_q[v]) q.push(v), in_q[v]=1;
            }
        }
    }
    return pre[sink_node]!=0;
}
int total_flow_value=0, total_cost_value=0;
void run_flow()
{
    while (spfa_algorithm())
    {
        int u=sink_node, f=flow[sink_node]; total_flow_value+=f; total_cost_value+=f*dist[sink_node];
        while (u!=start)
